package service

import (
	"context"
	"time"

	"github.com/anyproto/anytype-heart/pkg/lib/pinkha/capturecontrol"
)

var nativeSourceCaptures = capturecontrol.New(4)

// PinkhaCaptureLoadedAccountSource is the gomobile source-capture entry point.
// Call off the UI thread. The existing application must already hold the exact
// account and Space; sessionToken must be a current full unassociated native
// session. privateDirectory must already be canonical, non-symlink and 0700.
// The private bundle contains plaintext source/history/encryption metadata and
// must remain in private application storage. Its descriptor grants no writes.
// The context timeout is cooperative; it does not promise hard native IO expiry.
func PinkhaCaptureLoadedAccountSource(sessionToken, accountID, spaceID, privateDirectory, requestID string) ([]byte, error) {
	if !capturecontrol.ValidRequestID(requestID) {
		return nil, capturecontrol.ErrInvalidRequest
	}
	ctx, finish, err := nativeSourceCaptures.Begin(context.Background(), sessionToken, capturecontrol.CaptureRequestID(requestID), capturecontrol.MaximumDuration)
	if err != nil {
		return nil, err
	}
	defer finish()
	return mw.PinkhaCaptureLoadedAccountSource(ctx, sessionToken, accountID, spaceID, privateDirectory, requestID)
}

// PinkhaValidateLoadedAccountSourceCapture performs a new real native authority
// and source-checkpoint read for the original in-process capture. Its successful
// return is not semantic migration admission or a destination write permit.
func PinkhaValidateLoadedAccountSourceCapture(sessionToken, requestID, manifestSHA256 string) error {
	if !capturecontrol.ValidRequestID(requestID) {
		return capturecontrol.ErrInvalidRequest
	}
	ctx, finish, err := nativeSourceCaptures.Begin(context.Background(), sessionToken,
		capturecontrol.VerificationRequestID(requestID), time.Minute)
	if err != nil {
		return err
	}
	defer finish()
	return mw.PinkhaValidateLoadedAccountSourceCapture(ctx, sessionToken, requestID, manifestSHA256)
}

// PinkhaCancelLoadedAccountSourceCapture cancels only active capture/checkpoint
// calls created with this same token. Their slots stay owned until completion.
func PinkhaCancelLoadedAccountSourceCapture(sessionToken, requestID string) bool {
	if !capturecontrol.ValidRequestID(requestID) {
		return false
	}
	capture := nativeSourceCaptures.Cancel(sessionToken, capturecontrol.CaptureRequestID(requestID))
	verification := nativeSourceCaptures.Cancel(sessionToken, capturecontrol.VerificationRequestID(requestID))
	return capture || verification
}

// PinkhaReleaseLoadedAccountSourceCapture forgets only the original metadata
// binding and requests cancellation. Private recovery source files are retained.
func PinkhaReleaseLoadedAccountSourceCapture(sessionToken, requestID string) bool {
	PinkhaCancelLoadedAccountSourceCapture(sessionToken, requestID)
	return mw.PinkhaReleaseLoadedAccountSourceCapture(sessionToken, requestID)
}

